package project.init.framework.authen;import jakarta.servlet.ServletException;import jakarta.servlet.http.HttpServletRequest;import jakarta.servlet.http.HttpServletResponse;import org.apache.tomcat.util.bcel.Const;import org.springframework.http.HttpStatus;import org.springframework.security.core.AuthenticationException;import org.springframework.security.web.AuthenticationEntryPoint;import org.springframework.stereotype.Component;import project.init.framework.utils.Constants;import java.io.IOException;@Componentpublic class RestAuthenticationEntryPoint implements AuthenticationEntryPoint {    @Override    public void commence(HttpServletRequest request,                         HttpServletResponse response,                         AuthenticationException authException) throws IOException {        response.setContentType(Constants.APPLICATION_JSON);        response.setStatus(HttpServletResponse.SC_UNAUTHORIZED);        response.getWriter().write(HttpStatus.UNAUTHORIZED.getReasonPhrase());    }}